 var outer=new SplitContainer{Dock=DockStyle.Fill,Width=1400,SplitterDistance=660};Controls.Add(outer);videoHost=outer.Panel2;var inner=new SplitContainer{Dock=DockStyle.Fill,Width=650,SplitterDistance=285};outer.Panel1.Controls.Add(inner);inner.Panel1.Controls.Add(tree);inner.Panel1.Controls.Add(Ui.Label(title+"  ·  Countries",34));tree.BackColor=Ui.Surface;tree.ForeColor=Ui.Text;tree.ImageList=icons;
