 list.RetrieveVirtualItem+=(_,e)=>{if(e.ItemIndex>=visible.Length){e.Item=new ListViewItem("");return;}var entry=visible[e.ItemIndex];e.Item=new ListViewItem(new[]{entry.Media.Name,CatalogDirectory.English(entry.Location.Genre)});};list.DoubleClick+=(_,_)=>{if(Selected is{} c)play(c);};list.KeyDown+=(_,e)=>{if(e.KeyCode==Keys.Enter&&Selected is{} c)play(c);};
