 async Task Filter(){int version=++filterVersion;string text=search.Text,selectedCountry=country,selectedGenre=genre;var matches=await Task.Run(()=>entries.Where(e=>(selectedCountry.Length==0||e.Location.Country.Code==selectedCountry)&&(selectedGenre.Length==0||e.Location.Genre==selectedGenre)&&e.Media.Name.Contains(text,StringComparison.OrdinalIgnoreCase)).OrderBy(e=>e.Media.Name,StringComparer.OrdinalIgnoreCase).ToArray());if(IsDisposed||version!=filterVersion)return;list.VirtualListSize=0;visible=matches;list.VirtualListSize=visible.Length;path.Text=$"{(country.Length>0?ChannelDirectory.Countries[country].Name:"All countries")} › {(genre.Length>0?CatalogDirectory.English(genre):"All genres")}\n{visible.Length:N0} titles";list.Invalidate();}
